def derive(master: bytes, purpose: str, context: str = "") -> bytes:
    """32-byte subkey. Distinct (purpose, context) pairs give independent keys."""
    info = b"provenmark/v1/" + purpose.encode() + b"\x00" + context.encode()
    return HKDF(algorithm=hashes.SHA256(), length=32, salt=None, info=info).derive(master)


def commitment(subkey: bytes) -> str:
    """Hiding+binding commitment to a (high-entropy) key; publish/sign it now, reveal the key later."""
    return hashlib.sha256(b"provenmark/commit/v1" + subkey).hexdigest()


