def verify_signature(public_key: bytes, data: bytes, sig: bytes) -> bool:
    from cryptography.exceptions import InvalidSignature
    try:
        Ed25519PublicKey.from_public_bytes(public_key).verify(sig, data)
        return True
    except InvalidSignature:
        return False
